<?php if(user())redirect('profile.php');verify_csrf();if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$pass=$_POST['password']??'';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<6){flash('err','نام، ایمیل معتبر و رمز حداقل ۶ کاراکتری لازم است.');}else{try{$s=$pdo->prepare('INSERT INTO users(name,email,password_hash) VALUES(?,?,?)');$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);$_SESSION['uid']=$pdo->lastInsertId();flash('ok','ثبت‌نام با موفقیت انجام شد.');redirect('profile.php');}catch(PDOException $e){flash('err','این ایمیل قبلاً ثبت شده است.');}}}$title='ثبت‌نام';require __DIR__.'/partials/header.php'; ?>
<div class="panel" style="max-width:520px;margin:40px auto"><h1>ساخت حساب</h1><form method="post"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><div class="field"><label>نام و نام خانوادگی</label><input name="name" required></div><div class="field"><label>ایمیل</label><input type="email" name="email" required></div><div class="field"><label>رمز عبور</label><input type="password" name="password" minlength="6" required></div><button class="btn">ثبت‌نام</button></form></div><?php require __DIR__.'/partials/footer.php'; ?>
